(function(){'use strict';const API='https://api.aallyn.net';const STORAGE_PREFIX='btt_site_auth';const KEY_ACCESS=`${STORAGE_PREFIX}_access`;const KEY_REFRESH=`${STORAGE_PREFIX}_refresh`;const KEY_USER=`${STORAGE_PREFIX}_user`;let _captchaConfig=null;let _captchaConfigPromise=null;async function getCaptchaConfig(){if(_captchaConfig)return _captchaConfig;if(_captchaConfigPromise)return _captchaConfigPromise;_captchaConfigPromise=(async()=>{try{const r=await fetch(API+'/config');if(!r.ok)return null;const data=await r.json();_captchaConfig={provider:data.captcha_provider||'turnstile',sitekey:data.captcha_sitekey||null,};return _captchaConfig;}catch(_){return null;}})().finally(()=>{_captchaConfigPromise=null;});return _captchaConfigPromise;}
const _captchaScripts={hcaptcha:'https://hcaptcha.com/1/api.js?render=explicit',turnstile:'https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit',};let _captchaScriptLoaded=null;async function loadCaptchaScript(provider){if(_captchaScriptLoaded===provider)return true;if(_captchaScriptLoaded)return _captchaScriptLoaded===provider;const src=_captchaScripts[provider];if(!src)return false;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.async=true;s.defer=true;s.onload=()=>resolve();s.onerror=()=>reject(new Error('captcha script failed to load'));document.head.appendChild(s);});_captchaScriptLoaded=provider;return true;}
async function mountCaptcha($mount){const cfg=await getCaptchaConfig();if(!cfg||!cfg.sitekey)return()=>null;try{await loadCaptchaScript(cfg.provider);}catch(_){return()=>null;}
let token=null;let widgetId=null;const globalName=cfg.provider==='hcaptcha'?'hcaptcha':'turnstile';for(let i=0;i<40&&!window[globalName];i++){await new Promise((r)=>setTimeout(r,50));}
const widget=window[globalName];if(!widget)return()=>null;widgetId=widget.render($mount,{sitekey:cfg.sitekey,theme:'dark',callback:(t_)=>{token=t_;},'expired-callback':()=>{token=null;},'error-callback':()=>{token=null;},});return()=>{const out=token;if(out&&widget.reset&&widgetId!==null){try{widget.reset(widgetId);}catch(_){}
token=null;}
return out;};}
const tokens={get access(){try{return localStorage.getItem(KEY_ACCESS);}catch(_){return null;}},get refresh(){try{return localStorage.getItem(KEY_REFRESH);}catch(_){return null;}},save(access,refresh){try{if(access)localStorage.setItem(KEY_ACCESS,access);if(refresh)localStorage.setItem(KEY_REFRESH,refresh);}catch(_){}},clear(){try{localStorage.removeItem(KEY_ACCESS);localStorage.removeItem(KEY_REFRESH);localStorage.removeItem(KEY_USER);}catch(_){}},};async function call(path,opts={}){const url=path.startsWith('http')?path:API+path;const headers=Object.assign({},opts.headers||{});if(opts.json!==undefined){headers['Content-Type']='application/json';}
if(opts.auth!==false&&tokens.access){headers['Authorization']='Bearer '+tokens.access;}
const init={method:opts.method||(opts.json!==undefined?'POST':'GET'),headers,body:opts.json!==undefined?JSON.stringify(opts.json):opts.body,};let res=await fetch(url,init);if(res.status===401&&opts.auth!==false&&!opts._retried&&tokens.refresh){const ok=await refresh();if(ok){headers['Authorization']='Bearer '+tokens.access;res=await fetch(url,Object.assign({},init,{headers}));}else{tokens.clear();}}
return res;}
async function callJSON(path,opts){const res=await call(path,opts);let data=null;try{data=await res.json();}catch(_){}
return{ok:res.ok,status:res.status,data};}
async function refresh(){if(!tokens.refresh)return false;try{const r=await fetch(API+'/v1/site-auth/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:tokens.refresh}),});if(!r.ok)return false;const data=await r.json();tokens.save(data.access_token,data.refresh_token);return true;}catch(_){return false;}}
async function logout(){if(tokens.refresh){try{await fetch(API+'/v1/site-auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:tokens.refresh}),});}catch(_){}}
tokens.clear();document.dispatchEvent(new CustomEvent('btt-auth-changed',{detail:{user:null}}));}
let _meCache=null;let _meInflight=null;async function getMe({force=false}={}){if(!tokens.access)return null;if(!force&&_meCache)return _meCache;if(_meInflight)return _meInflight;_meInflight=(async()=>{const r=await callJSON('/v1/site-auth/me');if(r.ok&&r.data){_meCache=r.data;try{localStorage.setItem(KEY_USER,JSON.stringify(r.data));}catch(_){}
document.dispatchEvent(new CustomEvent('btt-auth-changed',{detail:{user:r.data}}));return r.data;}
return null;})().finally(()=>{_meInflight=null;});return _meInflight;}
function getCachedUser(){if(_meCache)return _meCache;try{const raw=localStorage.getItem(KEY_USER);if(raw){_meCache=JSON.parse(raw);return _meCache;}}catch(_){}
return null;}
function renderNav(user){const $el=document.getElementById('nav-account');if(!$el)return;if(!user){$el.dataset.state='out';$el.innerHTML=`
        <a class="nav-account-signin" href="/login" data-i18n>Sign in</a>`;rerunI18n();return;}
$el.dataset.state='in';const label=user.display_name||user.username||'?';const initials=(label.match(/[a-zA-Z0-9]/g)||['?'])[0].toUpperCase();$el.innerHTML=`
      <div class="nav-account-menu">
        <button type="button" class="nav-account-trigger" id="nav-account-trigger"
                aria-haspopup="true" aria-expanded="false" aria-controls="nav-account-panel">
          <span class="nav-account-avatar">${esc(initials)}</span>
          <span class="nav-account-name">${esc(label)}</span>
          <i class="fa-solid fa-chevron-down" aria-hidden="true"></i>
        </button>
        <div class="nav-account-panel" id="nav-account-panel" role="menu" hidden>
          <a class="nav-account-item" href="/dashboard" role="menuitem">
            <i class="fa-solid fa-gauge-high" aria-hidden="true"></i>
            <span data-i18n>Dashboard</span>
          </a>
          <button type="button" class="nav-account-item nav-account-item-danger"
                  id="nav-account-signout" role="menuitem">
            <i class="fa-solid fa-right-from-bracket" aria-hidden="true"></i>
            <span data-i18n>Sign out</span>
          </button>
        </div>
      </div>`;rerunI18n();const $trigger=document.getElementById('nav-account-trigger');const $panel=document.getElementById('nav-account-panel');const $signout=document.getElementById('nav-account-signout');const setOpen=(open)=>{$trigger.setAttribute('aria-expanded',String(open));$panel.hidden=!open;};setOpen(false);$trigger.addEventListener('click',(e)=>{e.stopPropagation();setOpen($panel.hidden);});document.addEventListener('click',(e)=>{if(!$el.contains(e.target))setOpen(false);});document.addEventListener('keydown',(e)=>{if(e.key==='Escape'&&!$panel.hidden){setOpen(false);$trigger.focus();}});$signout.addEventListener('click',async()=>{await logout();if(location.pathname==='/dashboard')location.href='/login';});}
function wireLoginForm(){const $form=document.getElementById('login-form');if(!$form)return;const $err=document.getElementById('login-error');const $submit=document.getElementById('login-submit');const $captcha=document.getElementById('login-captcha');let getCaptchaToken=()=>null;if($captcha){mountCaptcha($captcha).then((fn)=>{getCaptchaToken=fn;});}
$form.addEventListener('submit',async(e)=>{e.preventDefault();$err.hidden=true;$submit.disabled=true;const identifier=document.getElementById('login-identifier').value.trim();const password=document.getElementById('login-password').value;const captcha_token=getCaptchaToken();try{const r=await callJSON('/v1/site-auth/login',{method:'POST',json:{identifier,password,captcha_token},auth:false,});if(!r.ok){$err.textContent=errorMessage(r.data)||t('Sign-in failed.');$err.hidden=false;return;}
tokens.save(r.data.access_token,r.data.refresh_token);await getMe({force:true});const next=new URLSearchParams(location.search).get('next');location.href=next&&next.startsWith('/')?next:'/dashboard';}finally{$submit.disabled=false;}});const $resend=document.getElementById('resend-verify-link');if($resend){$resend.addEventListener('click',async(e)=>{e.preventDefault();const raw=document.getElementById('login-identifier').value.trim();if(raw.indexOf('@')<0){$err.textContent=t('Enter your email above first, then click resend.');$err.hidden=false;return;}
const r=await callJSON('/v1/site-auth/resend-verification',{method:'POST',json:{email:raw},auth:false,});$err.textContent=(r.data&&r.data.message)||t('Verification email sent.');$err.hidden=false;});}}
function wireSignupForm(){const $form=document.getElementById('signup-form');if(!$form)return;const $err=document.getElementById('signup-error');const $submit=document.getElementById('signup-submit');const $captcha=document.getElementById('signup-captcha');let getCaptchaToken=()=>null;if($captcha){mountCaptcha($captcha).then((fn)=>{getCaptchaToken=fn;});}
$form.addEventListener('submit',async(e)=>{e.preventDefault();$err.hidden=true;$submit.disabled=true;const username=document.getElementById('signup-username').value.trim();const email=document.getElementById('signup-email').value.trim();const password=document.getElementById('signup-password').value;const displayName=(document.getElementById('signup-display-name').value||'').trim();const captcha_token=getCaptchaToken();try{const r=await callJSON('/v1/site-auth/signup',{method:'POST',json:{username,email,password,display_name:displayName||null,captcha_token,},auth:false,});if(!r.ok){$err.textContent=errorMessage(r.data)||t('Sign-up failed.');$err.hidden=false;return;}
const login=await callJSON('/v1/site-auth/login',{method:'POST',json:{identifier:username,password,captcha_token:null},auth:false,});if(login.ok){tokens.save(login.data.access_token,login.data.refresh_token);await getMe({force:true});}
location.href='/dashboard';}finally{$submit.disabled=false;}});}
function t(s){return window.BTTi18n&&window.BTTi18n.t?window.BTTi18n.t(s):s;}
function rerunI18n(){if(window.BTTi18n&&window.BTTi18n.refresh)window.BTTi18n.refresh();}
function esc(s){return String(s??'').replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function errorMessage(data){if(!data)return null;if(data.error&&data.error.message)return data.error.message;if(typeof data.detail==='string')return data.detail;if(Array.isArray(data.detail)&&data.detail.length){const first=data.detail[0];return first.msg||JSON.stringify(first);}
return null;}
window.addEventListener('storage',(e)=>{if(e.key===KEY_ACCESS||e.key===KEY_REFRESH||e.key===KEY_USER){_meCache=null;bootNav();}});async function bootNav(){const cached=getCachedUser();renderNav(cached);if(!tokens.access){renderNav(null);return;}
const fresh=await getMe();renderNav(fresh);}
function boot(){bootNav();wireLoginForm();wireSignupForm();document.addEventListener('btt-lang-changed',()=>{renderNav(getCachedUser());});}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',boot);}else{boot();}
window.BTTAuth={call,callJSON,refresh,logout,getMe,getCachedUser,tokens,API,errorMessage,mountCaptcha,getCaptchaConfig,};})();